'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\n\n', [[''], ['']]],
  ['\r\n', [['']]],
  ['\r\r\n\n', [[''], [''], ['']]],
  ['a\r\nb\rc\nd', [['a'], ['b'], ['c'], ['d']]],
  ['a\n', [['a']]],
  [',', [['', '']]],
  ['left,,right,', [['left', '', 'right', '']]],
  ['""', [['']]],
  ['""\n', [['']]],
  ['"a,b","say ""hi"""\n', [['a,b', 'say "hi"']]],
  ['"first\r\nsecond\rthird\nfourth",tail\r\n', [['first\r\nsecond\rthird\nfourth', 'tail']]],
  ['a"b,c"d', [['a"b', 'c"d']]],
  [' "quoted"', [[' "quoted"']]],
  ['""""', [['"']]],
  ['\uFEFFa,\uFEFFb', [['a', '\uFEFFb']]],
  ['\uFEFF\uFEFF', [['\uFEFF']]],
  ['😀,x', [['😀', 'x']]],
  ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';' }],
  ['a\tb\n', [['a', 'b']], { delimiter: '\t' }],
  ['a b', [['a', 'b']], { delimiter: ' ' }],
  ['a\0b', [['a', 'b']], { delimiter: '\0' }],
  ['a\uD83Db', [['a', 'b']], { delimiter: '\uD83D' }],
  ['\uFEFFa\uFEFFb', [['a', 'b']], { delimiter: '\uFEFF' }],
];
let partitions = 0;
function checkChunks(text, expected, options, chunks) {
  const parser = createParser(options);
  const records = [];
  assert.deepEqual(parser.push(''), []);
  for (const chunk of chunks) {
    records.push(...parser.push(chunk));
    assert.deepEqual(parser.push(''), []);
  }
  records.push(...parser.end());
  assert.deepEqual(records, expected, JSON.stringify({ text, chunks }));
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
  partitions++;
}
for (const [text, expected, options] of cases) {
  assert.deepEqual(parse(text, options), expected);
  for (let first = 0; first <= text.length; first++) {
    for (let second = first; second <= text.length; second++) {
      checkChunks(text, expected, options,
        [text.slice(0, first), text.slice(first, second), text.slice(second)]);
    }
  }
  checkChunks(text, expected, options, text.split(''));
}

