'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\n\n', [[''], ['']]],
  ['\r\n', [['']]],
  ['\r\r\n\n', [[''], [''], ['']]],
  ['a\r\nb\rc\nd', [['a'], ['b'], ['c'], ['d']]],
  ['a\n', [['a']]],
  [',', [['', '']]],
  ['left,,right,', [['left', '', 'right', '']]],
  ['""', [['']]],
  ['""\n', [['']]],
  ['"a,b","say ""hi"""\n', [['a,b', 'say "hi"']]],
  ['"first\r\nsecond\rthird\nfourth",tail\r\n', [['first\r\nsecond\rthird\nfourth', 'tail']]],
  ['a"b,c"d', [['a"b', 'c"d']]],
  [' "quoted"', [[' "quoted"']]],
  ['""""', [['"']]],
  ['\uFEFFa,\uFEFFb', [['a', '\uFEFFb']]],
  ['\uFEFF\uFEFF', [['\uFEFF']]],
  ['😀,x', [['😀', 'x']]],
  ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';' }],
  ['a\tb\n', [['a', 'b']], { delimiter: '\t' }],
  ['a b', [['a', 'b']], { delimiter: ' ' }],
  ['a\0b', [['a', 'b']], { delimiter: '\0' }],
  ['a\uD83Db', [['a', 'b']], { delimiter: '\uD83D' }],
  ['\uFEFFa\uFEFFb', [['a', 'b']], { delimiter: '\uFEFF' }],
];
let partitions = 0;
function checkChunks(text, expected, options, chunks) {
  const parser = createParser(options);
  const records = [];
  assert.deepEqual(parser.push(''), []);
  for (const chunk of chunks) {
    records.push(...parser.push(chunk));
    assert.deepEqual(parser.push(''), []);
  }
  records.push(...parser.end());
  assert.deepEqual(records, expected, JSON.stringify({ text, chunks }));
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
  partitions++;
}
for (const [text, expected, options] of cases) {
  assert.deepEqual(parse(text, options), expected);
  for (let first = 0; first <= text.length; first++) {
    for (let second = first; second <= text.length; second++) {
      checkChunks(text, expected, options,
        [text.slice(0, first), text.slice(first, second), text.slice(second)]);
    }
  }
  checkChunks(text, expected, options, text.split(''));
}

const stream = createParser({ header: true });
assert.deepEqual(stream.push('a\r'), [['a']]);
assert.deepEqual(stream.push(''), []);
assert.deepEqual(stream.push('\nb\n\n"c\r'), [['b'], ['']]);
assert.deepEqual(stream.push('\nd"\r'), [['c\r\nd']]);
assert.deepEqual(stream.push('\nlast,'), []);
assert.deepEqual(stream.end(), [['last', '']]);
assert.deepEqual(stream.end(), []);
assert.throws(() => stream.push(''), Error);

const independentA = createParser();
const independentB = createParser({ delimiter: ';' });
assert.deepEqual(independentA.push('"a'), []);
assert.deepEqual(independentB.push('b;c\n'), [['b', 'c']]);
assert.deepEqual(independentA.push('"\n'), [['a']]);
assert.deepEqual(independentB.end(), []);
assert.deepEqual(independentA.end(), []);

for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, 1, {}, false]) {
  assert.throws(() => createParser({ delimiter }), RangeError);
}
assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
const validated = createParser();
for (const chunk of [undefined, null, 1, {}, [], Buffer.from('a'), new String('a')]) {
  assert.throws(() => validated.push(chunk), TypeError);
}
assert.deepEqual(validated.push('a\n'), [['a']]);
assert.deepEqual(validated.end(), []);
assert.throws(() => parse(null), TypeError);

const errors = [
  ['"a"x', 1, 'push'],
  ['"a" ', 1, 'push'],
  ['a\r\n"b"x', 2, 'push'],
  ['"a\r\nb\rc\nd"x', 4, 'push'],
  ['"a', 1, 'end'],
  ['"a\r\n', 2, 'end'],
  ['"a\r\nb\rc\n', 4, 'end'],
  ['a\r\n"b', 2, 'end'],
  ['"""', 1, 'end'],
];
for (const [text, line, phase] of errors) {
  const matches = error => error instanceof SyntaxError &&
    new RegExp(`\\bline ${line}\\b`).test(error.message);
  for (let split = 0; split <= text.length; split++) {
    const parser = createParser();
    if (phase === 'push') {
      assert.throws(() => {
        parser.push(text.slice(0, split));
        parser.push('');
        parser.push(text.slice(split));
      }, matches);
    } else {
      parser.push(text.slice(0, split));
      parser.push('');
      parser.push(text.slice(split));
      assert.throws(() => parser.end(), matches);
    }
  }
  assert.throws(() => parse(text), matches);
}

const objects = parse('x,x,x_2,x,__proto__,constructor,toString,\n1,2,3,4,5,6,7,8\na\n', { header: true });
assert.deepEqual(Object.keys(objects[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString', '']);
assert.equal(Object.getPrototypeOf(objects[0]), Object.prototype);
assert.equal(objects[0].__proto__, '5');
assert.equal(objects[0].constructor, '6');
assert.equal(objects[0].toString, '7');
assert.equal(objects[0][''], '8');
assert.deepEqual(Object.values(objects[1]), ['a', '', '', '', '', '', '', '']);
assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('a,b', { header: true }), []);
assert.deepEqual(parse('a\nb,extra', { header: true }), [{ a: 'b' }]);
assert.deepEqual(parse('a\nb', { header: false }), [['a'], ['b']]);
const frozenRecords = Object.freeze([Object.freeze(['one']), Object.freeze(['two', 'extra'])]);
const frozenHeader = Object.freeze(['__proto__', '__proto__', 'constructor']);
const frozenOptions = Object.freeze({ header: frozenHeader });
const converted = toObjects(frozenRecords, frozenOptions);
assert.deepEqual(Object.keys(converted[0]), ['__proto__', '__proto___2', 'constructor']);
assert.deepEqual(Object.values(converted[0]), ['one', '', '']);
assert.deepEqual(Object.values(converted[1]), ['two', 'extra', '']);
assert.equal(Object.getPrototypeOf(converted[0]), Object.prototype);
assert.deepEqual(toObjects(frozenRecords, { header: [] }), [{}, {}]);
assert.deepEqual(frozenRecords, [['one'], ['two', 'extra']]);
assert.deepEqual(frozenHeader, ['__proto__', '__proto__', 'constructor']);
console.log(`CSV smoke checks passed: ${cases.length} fixtures, ${partitions} chunk partitions, immediate emission, validation, lifecycle, physical lines, and header/helper behavior.`);
